"use client";

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { DataGridProvider, DataGridRoot, DataGridHeader, DataGridBody, defineColumns, useDataGridApi } from "@/registry/default/components/data-grid/data-grid";
import { DataGridToolbar, DataGridSearch, DataGridFilterMenu, DataGridColumnsMenu } from "@/registry/default/components/data-grid-toolbar/data-grid-toolbar";
import { DataGridPaginationBar } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { useDataGridServerRows } from "@/registry/default/components/data-grid-server/data-grid-server";
import { createRemoteServer, type RemoteFilterNode, type RemoteServer } from "./fake-remote-server";
import { DEALERSHIPS, MAKES, REGIONS, generateSales, type SaleRow } from "./sales-data";

const columns = defineColumns<SaleRow>()([
  { id: "customer", header: "Customer", accessorKey: "customer", type: "text", width: 130, flex: 2 },
  { id: "region", header: "Region", accessorKey: "region", type: "select", options: { choices: REGIONS }, width: 90, filterable: true },
  { id: "dealership", header: "Dealership", accessorKey: "dealership", type: "select", options: { choices: DEALERSHIPS }, width: 150, filterable: true },
  { id: "make", header: "Make", accessorKey: "make", type: "select", options: { choices: MAKES }, width: 100, filterable: true },
  { id: "model", header: "Model", accessorKey: "model", type: "text", width: 90, flex: 1 },
  { id: "financed", header: "Financed", accessorKey: "financed", type: "checkbox", width: 90 },
  { id: "price", header: "Price", accessorKey: "price", type: "number", width: 90, flex: 1 },
] as const);

type Mode = "pages" | "scroll";

/**
 * The full server-side contract in one grid: header-click sort, filter menu, quick search, and paging are sent
 * to the fake server (~300 ms per request) and applied there - nothing is filtered or sorted client-side.
 * `useDataGridServerRows` owns the spec, aborts a stale request, and keeps the rows on screen while the next ones
 * load. `mode: "pages"` fetches one page per state and goes back to page 1 on a spec change; `mode: "scroll"`
 * sizes the grid from `totalRowCount` and fetches the blocks the rendered rows need. Edits go to the server from
 * `onSave`, then the rows are fetched again so you see the server's truth. Pages mode prefetches the next page, so
 * Next shows it with no wait; the toggle revalidates the rows every 10 seconds. The grid sorts by price. The Server
 * pushes switch pushes price changes every 500 ms: a row whose price the sort reads keeps its place and turns
 * dim and italic (`data-row-stale`) until the hook reshapes (a refresh) and the server places it. Delete on server
 * pushes a delete. The reshape delay select sets `reshapeDelayMs`: off waits for a refresh, one second reshapes after the pushes.
 */
export default function DataGridServerSideDemo(): ReactNode {
  const [mode, setMode] = useState<Mode>("pages");
  const remote = useMemo(() => createRemoteServer({ rows: generateSales(1000) }), []);
  const [revalidate, setRevalidate] = useState(false);
  const [live, setLive] = useState(false);
  const [reshapeDelayMs, setReshapeDelay] = useState<"off" | "1000">("off");
  const push = { live, reshapeDelayMs: reshapeDelayMs === "off" ? (false as const) : Number(reshapeDelayMs) };
  return (
    <div className="w-full flex flex-col gap-2">
      <div className="flex flex-wrap items-center gap-2">
        <Button type="button" size="sm" variant={mode === "pages" ? "default" : "outline"} aria-pressed={mode === "pages"} onClick={() => setMode("pages")}>
          Pages
        </Button>
        <Button type="button" size="sm" variant={mode === "scroll" ? "default" : "outline"} aria-pressed={mode === "scroll"} onClick={() => setMode("scroll")}>
          Scroll
        </Button>
        <Button type="button" size="sm" variant={revalidate ? "default" : "outline"} aria-pressed={revalidate} onClick={() => setRevalidate((on) => !on)}>
          Revalidate every 10 s
        </Button>
        <label className="flex items-center gap-2 text-sm">
          <Switch checked={live} onCheckedChange={setLive} aria-label="Server pushes" />
          Server pushes
        </label>
        <Select value={reshapeDelayMs} onValueChange={(value) => setReshapeDelay(value as "off" | "1000")}>
          <SelectTrigger aria-label="Reshape delay" className="w-40">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="off">Reshape: off</SelectItem>
            <SelectItem value="1000">Reshape: 1 s</SelectItem>
          </SelectContent>
        </Select>
        <span className="text-sm text-muted-foreground">sort, filter, search and paging are all server-side</span>
      </div>
      {mode === "pages" ? <PagesGrid key="pages" remote={remote} revalidate={revalidate} {...push} /> : <ScrollGrid key="scroll" remote={remote} revalidate={revalidate} {...push} />}
    </div>
  );
}

type Remote = RemoteServer<SaleRow>;
type PushProps = { remote: Remote; live: boolean; reshapeDelayMs: number | false };

const BY_PRICE = { sorts: [{ columnId: "price", direction: "desc" as const }] };
const STALE_ROW = "[&_[data-row-stale]]:text-muted-foreground [&_[data-row-stale]]:italic";

/** Pushes the server's price changes into the grid while `live` is on, and deletes the first row on the server on demand. */
function PushControls({ remote, live }: { remote: Remote; live: boolean }): ReactNode {
  const api = useDataGridApi<SaleRow>();
  useEffect(() => {
    if (!live) return;
    const timer = setInterval(() => {
      const ids = api.getViewRowIds({ loaded: true }).slice(0, 8);
      api.actions.updateRows(remote.bumpNumbers(ids.slice(0, 3), "price", (price) => Math.max(15000, price + Math.round(((Math.random() - 0.5) * 6000) / 100) * 100)), { source: "stream" });
    }, 500);
    return () => clearInterval(timer);
  }, [api, remote, live]);
  return (
    <Button
      type="button"
      size="sm"
      variant="outline"
      onClick={() => {
        const first = api.getRow(0);
        if (!first) return;
        remote.remove([first.id]);
        api.actions.deleteRows([first.id], { source: "stream" });
      }}
    >
      Delete on server
    </Button>
  );
}

function PagesGrid({ remote, revalidate, live, reshapeDelayMs }: PushProps & { revalidate: boolean }): ReactNode {
  const server = useDataGridServerRows<SaleRow>({
    defaultPageSize: 25,
    defaultSpec: BY_PRICE,
    prefetchNextPage: true,
    revalidateIntervalMs: revalidate ? 10_000 : undefined,
    reshapeDelayMs,
    onSave: async (change) => remote.applyOps(change.ops),
    fetchRows: async ({ spec, page, pageSize, signal }) => {
      const answer = await remote.fetchPage({ page, pageSize, sorts: spec.sorts, filters: spec.filters as RemoteFilterNode[], search: spec.searchText, signal });
      return { rows: answer.rows, totalRowCount: answer.total };
    },
  });

  return (
    <>
      <div className="text-sm text-muted-foreground">{server.totalRowCount === null ? "Loading…" : `Page ${server.pager.page} of ${server.pager.pageCount} · ${server.totalRowCount} rows on the server`}</div>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider
          {...server.providerProps}
          columns={columns}
          headerClickBehavior="sort"
        >
          <DataGridToolbar>
            <DataGridSearch />
            <DataGridFilterMenu />
            <DataGridColumnsMenu />
            <PushControls remote={remote} live={live} />
          </DataGridToolbar>
          <DataGridRoot className={`min-h-0 flex-1 rounded-none border-none ${STALE_ROW}`} {...server.rootProps}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
        <DataGridPaginationBar {...server.pager} />
      </div>
    </>
  );
}

function ScrollGrid({ remote, revalidate, live, reshapeDelayMs }: PushProps & { revalidate: boolean }): ReactNode {
  const server = useDataGridServerRows<SaleRow>({
    mode: "scroll",
    defaultSpec: BY_PRICE,
    revalidateIntervalMs: revalidate ? 10_000 : undefined,
    reshapeDelayMs,
    onSave: async (change) => remote.applyOps(change.ops),
    fetchRows: async ({ spec, start, end, signal }) => {
      const answer = await remote.fetchRange({ start, end, sorts: spec.sorts, filters: spec.filters as RemoteFilterNode[], search: spec.searchText, signal });
      return { rows: answer.rows, totalRowCount: answer.total };
    },
  });

  return (
    <>
      <div className="text-sm text-muted-foreground">{server.totalRowCount === null ? "Loading…" : `${server.totalRowCount} rows on the server · ${server.unloadedCount} not loaded yet`}</div>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider
          {...server.providerProps}
          columns={columns}
          headerClickBehavior="sort"
        >
          <DataGridToolbar>
            <DataGridSearch />
            <DataGridFilterMenu />
            <DataGridColumnsMenu />
            <PushControls remote={remote} live={live} />
          </DataGridToolbar>
          <DataGridRoot className={`min-h-0 flex-1 rounded-none border-none ${STALE_ROW}`} {...server.rootProps}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </>
  );
}

import { applyChange, type DataChange } from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

const collator = new Intl.Collator("en-US", { numeric: true, sensitivity: "base" });

export type RemoteSort = { columnId: string; direction: "asc" | "desc" };
export type RemoteFilter = { columnId: string; operator: string; value?: string | [string, string] | string[] };
export type RemoteFilterGroup = { join: "and" | "or"; not?: boolean; filters: readonly RemoteFilterNode[] };
export type RemoteFilterNode = RemoteFilter | RemoteFilterGroup;
export type RemoteQuery = {
  page: number;
  pageSize: number;
  search?: string;
  sorts?: readonly RemoteSort[];
  filters?: readonly RemoteFilterNode[];
  signal?: AbortSignal;
};

const LATENCY_MS = 300;
const MAX_FILTER_DEPTH = 2;
const MAX_FILTER_LEAVES = 64;
const MAX_FILTER_GROUPS = 16;
const DEMO_FILTERABLE_COLUMNS: ReadonlySet<string> = new Set(["id", "name", "email", "age", "active", "role", "joined", "score"]);

const isGroup = (node: RemoteFilterNode): node is RemoteFilterGroup => "filters" in node;

/** Checks an untrusted filter tree before it is evaluated: depth, group count, leaf count, and join values. A real server also caps the request body size. */
function assertFilterTree(nodes: readonly RemoteFilterNode[], allowed: ReadonlySet<string>): void {
  let leaves = 0;
  let groups = 0;
  const walk = (list: readonly RemoteFilterNode[], depth: number) => {
    if (!Array.isArray(list)) throw new Error("invalid filter tree");
    for (const node of list as readonly RemoteFilterNode[]) {
      if (isGroup(node)) {
        if (depth >= MAX_FILTER_DEPTH || ++groups > MAX_FILTER_GROUPS || (node.join !== "and" && node.join !== "or")) throw new Error("invalid filter group");
        walk(node.filters, depth + 1);
      } else {
        if (!allowed.has(node.columnId) || ++leaves > MAX_FILTER_LEAVES) throw new Error("invalid filter");
      }
    }
  };
  walk(nodes, 0);
}

function delay(signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, LATENCY_MS);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("aborted", "AbortError"));
    });
  });
}

/**
 * Fake "database" of 1,000 rows behind a 300 ms round trip for the server-side examples:
 * `fetchPage` applies search/filter/sort on the "server" and returns one page plus the total;
 * `applyOps` writes the grid's committed operations back into the store (a stand-in for your API route),
 * so edits survive a refetch. `rows` replaces the people rows, and every key of its first row is filterable.
 */
export function createRemoteServer<T extends { id: string }>(options: { rows: readonly T[] }): RemoteServer<T>;
export function createRemoteServer(): RemoteServer<DemoRow>;
export function createRemoteServer<T extends { id: string }>(options: { rows?: readonly T[] } = {}): RemoteServer<T> {
  return createServer(options);
}

export type RemoteServer<T extends { id: string } = DemoRow> = ReturnType<typeof createServer<T>>;

function createServer<T extends { id: string }>(options: { rows?: readonly T[] }) {
  const rows = new Map<string, T>((options.rows ?? (generateDemoRows(1000) as unknown as readonly T[])).map((row) => [row.id, row]));
  const filterable = options.rows ? new Set(Object.keys(options.rows[0] ?? {})) : DEMO_FILTERABLE_COLUMNS;
  let order = [...rows.keys()];

  const cell = (row: T, columnId: string): string => {
    const value = row[columnId as keyof T];
    return value == null ? "" : String(value);
  };

  const matchFilter = (row: T, filter: RemoteFilter): boolean => {
    const text = cell(row, filter.columnId);
    const num = Number(text);
    const v = filter.value;
    switch (filter.operator) {
      case "contains":
        return text.toLowerCase().includes(String(v).toLowerCase());
      case "notContains":
        return !text.toLowerCase().includes(String(v).toLowerCase());
      case "equals":
        return text === String(v);
      case "notEquals":
        return text !== String(v);
      case "startsWith":
        return text.startsWith(String(v));
      case "endsWith":
        return text.endsWith(String(v));
      case "empty":
        return text === "";
      case "notEmpty":
        return text !== "";
      case "gt":
        return !Number.isNaN(num) && num > Number(v);
      case "gte":
        return !Number.isNaN(num) && num >= Number(v);
      case "lt":
        return !Number.isNaN(num) && num < Number(v);
      case "lte":
        return !Number.isNaN(num) && num <= Number(v);
      case "isBetween": {
        const [min, max] = v as [string, string];
        if (!Number.isNaN(num)) return (min === "" || num >= Number(min)) && (max === "" || num <= Number(max));
        return (min === "" || text >= min) && (max === "" || text <= max);
      }
      case "isAnyOf":
        return (v as string[]).some((entry) => entry.toLowerCase() === text.toLowerCase());
      case "isNoneOf":
        return !(v as string[]).some((entry) => entry.toLowerCase() === text.toLowerCase());
      default:
        return true;
    }
  };

  async function select(query: Pick<RemoteQuery, "search" | "sorts" | "filters" | "signal">): Promise<T[]> {
    await delay(query.signal);
    let list = order.map((id) => rows.get(id)!);
    if (query.search) {
      const needle = query.search.toLowerCase();
      list = list.filter((row) => Object.values(row).some((value) => String(value).toLowerCase().includes(needle)));
    }
    const filters = query.filters ?? [];
    if (filters.length > 0) {
      assertFilterTree(filters, filterable);
      const matchNode = (row: T, node: RemoteFilterNode): boolean => {
        if (!isGroup(node)) return matchFilter(row, node);
        if (node.filters.length === 0) return true;
        const match = node.join === "or" ? node.filters.some((f) => matchNode(row, f)) : node.filters.every((f) => matchNode(row, f));
        return node.not === true ? !match : match;
      };
      list = list.filter((row) => filters.every((f) => matchNode(row, f)));
    }
    const sorts = query.sorts ?? [];
    if (sorts.length > 0) {
      list = [...list].sort((a, b) => {
        for (const s of sorts) {
          const av = a[s.columnId as keyof T];
          const bv = b[s.columnId as keyof T];
          const delta = typeof av === "number" && typeof bv === "number" ? av - bv : collator.compare(String(av), String(bv));
          if (delta !== 0) return s.direction === "asc" ? delta : -delta;
        }
        return 0;
      });
    }
    return list;
  }

  async function fetchPage(query: RemoteQuery): Promise<{ rows: T[]; total: number }> {
    const list = await select(query);
    const start = (query.page - 1) * query.pageSize;
    return { rows: list.slice(start, start + query.pageSize), total: list.length };
  }

  /** The rows `[start, end)` of the filtered, sorted list plus its total, for a lazy grid. */
  async function fetchRange(query: Omit<RemoteQuery, "page" | "pageSize"> & { start: number; end: number }): Promise<{ rows: T[]; total: number }> {
    const list = await select(query);
    return { rows: list.slice(query.start, query.end), total: list.length };
  }

  /** A keyset page: the rows after the opaque `after` cursor, and the cursor of the next page (`null` at the end). No count. */
  async function fetchAfter(query: Omit<RemoteQuery, "page" | "pageSize"> & { after?: string; limit: number }): Promise<{ rows: T[]; next: string | null }> {
    const list = await select(query);
    const last = query.after === undefined ? -1 : query.after.startsWith("after:") ? Number(query.after.slice("after:".length)) : Number.NaN;
    if (!Number.isSafeInteger(last) || last < -1) throw new Error("invalid cursor");
    const rows = list.slice(last + 1, last + 1 + query.limit);
    return { rows, next: last + 1 + rows.length < list.length ? `after:${last + rows.length}` : null };
  }

  /** The distinct values of a column with their row counts, filtered by a case-insensitive `search` and capped at `limit`. */
  async function fetchValues(query: { columnId: string; search: string; filters?: readonly RemoteFilterNode[]; limit?: number; signal?: AbortSignal }): Promise<{ values: { value: string; count: number }[] }> {
    if (!filterable.has(query.columnId)) throw new Error("invalid column");
    const list = await select({ filters: query.filters, signal: query.signal });
    const counts = new Map<string, number>();
    const needle = query.search.toLowerCase();
    for (const row of list) {
      const label = cell(row, query.columnId);
      if (needle === "" || label.toLowerCase().includes(needle)) counts.set(label, (counts.get(label) ?? 0) + 1);
    }
    const values = [...counts].map(([value, count]) => ({ value, count })).sort((a, b) => collator.compare(a.value, b.value));
    return { values: values.slice(0, query.limit ?? 200) };
  }

  function applyOps(ops: DataChange<T>["ops"]): void {
    const next = applyChange(order.map((id) => rows.get(id)!), { ops, source: "app" }, (row) => row.id);
    rows.clear();
    for (const row of next) rows.set(row.id, row);
    order = next.map((row) => row.id);
  }

  /** Sets a new value on the server for the number column `columnId` of each known row and returns the matching pushes. */
  function bumpNumbers(ids: readonly string[], columnId: string, next: (value: number) => number): { rowId: string; changes: Record<string, number> }[] {
    const pushes: { rowId: string; changes: Record<string, number> }[] = [];
    for (const id of ids) {
      const row = rows.get(id);
      if (!row) continue;
      const value = next(Number(row[columnId as keyof T]));
      rows.set(id, { ...row, [columnId]: value });
      pushes.push({ rowId: id, changes: { [columnId]: value } });
    }
    return pushes;
  }

  /** Deletes rows on the server, as another client would. */
  function remove(ids: readonly string[]): void {
    for (const id of ids) rows.delete(id);
    order = order.filter((id) => rows.has(id));
  }

  return { total: rows.size, fetchPage, fetchRange, fetchAfter, fetchValues, applyOps, bumpNumbers, remove };
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}

/** One car sold by a dealership. */
export type SaleRow = {
  id: string;
  soldOn: string;
  region: string;
  dealership: string;
  salesperson: string;
  make: string;
  model: string;
  customer: string;
  price: number;
  discount: number;
  financed: boolean;
};

export const REGIONS = ["North", "South", "East", "West"];
export const DEALERSHIPS = ["Northgate Motors", "Pine Ridge Cars", "Bayview Autos", "Southfield Motors", "Eastbrook Cars", "Harbor Point Motors", "Westlake Autos", "Canyon Road Motors"];
export const MAKES = ["Kestrel", "Marlow", "Nordvik", "Solenne", "Vantor"];
const SALESPEOPLE = ["Dana Brooks", "Eli Moreno", "Fern Walsh", "Gus Ortega", "Hana Ito", "Ivan Petrov", "Jade Lin", "Kofi Mensah", "Lena Fischer", "Milo Grant", "Nia Duarte", "Omar Aziz", "Pia Lund", "Raul Vega", "Sana Mir", "Theo Clark"];
const MODELS = [["Brook", "Glide", "Summit"], ["Coast", "Harbor", "Tide"], ["Birch", "Fjord", "Frost"], ["Dawn", "Lumen", "Opal"], ["Ember", "Flint", "Quarry"]];
// Unequal shares per region and a different make mix in each region, so group totals differ.
const REGION_SLOTS = [0, 0, 0, 0, 1, 1, 1, 2, 2, 3];
const MAKE_MIX = [
  [0, 0, 0, 1, 2, 3, 4, 1],
  [1, 1, 1, 2, 0, 3, 4, 2],
  [2, 2, 3, 3, 3, 0, 1, 4],
  [4, 4, 4, 3, 0, 1, 2, 4],
];
const FIRST = ["Alex", "Sam", "Jordan", "Taylor", "Morgan", "Casey", "Riley", "Jamie", "Avery", "Quinn", "Drew", "Robin"];
const LAST = ["Smith", "Garcia", "Chen", "Patel", "Novak", "Okafor", "Larsen", "Rossi", "Kim", "Silva", "Meyer", "Haddad"];

/** `count` fictional car sales. Index arithmetic instead of `Math.random` keeps the server and client markup equal. */
export const generateSales = (count: number): SaleRow[] =>
  Array.from({ length: count }, (_, index) => {
    const region = REGION_SLOTS[index % REGION_SLOTS.length]!;
    const mix = MAKE_MIX[region]!;
    const make = mix[Math.floor(index / REGION_SLOTS.length) % mix.length]!;
    const model = Math.floor(index / 80) % 3;
    const dealership = region * 2 + (Math.floor(index / 7) % 3 === 0 ? 1 : 0);
    return {
      id: `sale-${index + 1}`,
      soldOn: new Date(Date.UTC(2025, 0, 1 + ((index * 7) % 365))).toISOString().slice(0, 10),
      region: REGIONS[region]!,
      dealership: DEALERSHIPS[dealership]!,
      salesperson: SALESPEOPLE[dealership * 2 + (Math.floor(index / 13) % 2)]!,
      make: MAKES[make]!,
      model: MODELS[make]![model]!,
      customer: `${FIRST[Math.floor(index / 5) % FIRST.length]!} ${LAST[(index * 7) % LAST.length]!}`,
      price: 21000 + make * 6000 + model * 9000 + ((index * 37) % 41) * 100,
      discount: ((index * 7) % 13) * 250,
      financed: index % 3 !== 0,
    };
  });
